const float PI = 3.14159265358;

vec2 Projection(vec2 p, float S) {
#ifdef SphereProjection
    if (length(p) == 0) return p;
    return normalize(p) * tan(length(p) * S);
#else
    return p * S;
#endif
}

vec3 ACESFilm(vec3 x) {
    float tA = 2.51;
    float tB = 0.03;
    float tC = 2.43;
    float tD = 0.59;
    float tE = 0.14;
    return clamp((x * (tA * x + tB)) / (x * (tC * x + tD) + tE), 0.0, 1.0);
}


vec2 rot(vec2 a, float theta) {
    return a.xx * vec2(cos(theta), sin(theta)) + a.yy * vec2(-sin(theta), cos(theta));
}


vec3 rot(vec3 a, vec3 angle) {
    a.yz = rot(a.yz, angle.x);
    a.xz = rot(a.xz, angle.y);
    a.xy = rot(a.xy, angle.z);
    return a;
}


float luma(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

// Calculates the distance from a specified position to the outer edge of the atmosphere
// R: Radius of the Earth
// y: Current height (distance from the center of the Earth)
// A: The y-component of the viewing direction, used for perspective calculation
float distance_to_surface(float R, float y, float A) {
    // return max((R-y)/max(A,1e-5),0.); // Parallel atmosphere assumption
    return max(sqrt(R * R - y * y * (1. - A * A)) - y * A, 0.); // Spherical atmosphere assumption
}

// Calculates the background color
vec4 background(float pos_y, in vec3 n, in vec3 lightDir) {
    vec3 n0 = n;
    const float P = 3000.;    // Thickness of the atmosphere
    const float k = 0.25;     // Mixing coefficient for Rayleigh and Mie scattering
    vec3 Rayleigh = 1.0e10 * pow(vec3(1. / 700., 1. / 520., 1. / 450.), vec3(4)); // Rayleigh scattering coefficient, inversely proportional to the fourth power of the wavelength
    vec3 Mie = vec3(luma(Rayleigh)); // Mie scattering coefficient, proportional to luminance
    const float R = 6370000. * 1.25; // Radius of the Earth

    vec3 k0 = mix(Rayleigh, Mie, k); // Mix Rayleigh and Mie scattering coefficients

    vec3 Q = k0 / (P * P); // Atmospheric absorption coefficient
    const vec3 Sun = vec3(50, 50, 50); // Color of the sun
    vec3 g0 = mix(Rayleigh, vec3(0.7), k); // Single scattering factor

    // Calculate the Mie scattering phase function (Henyey-Greenstein approximation)
    vec3 g = 3. / (8. * PI) * (1. + pow(dot(n, lightDir), 2.)) * (1. - g0 * g0) / (2. + g0 * g0) / pow(1. + g0 * g0 - 2. * g0 * dot(lightDir, n), vec3(1.5));
    vec3 t = Q * 0.5 * (P - pos_y); // Optical depth

    // Calculate the distance from the viewpoint to the outer edge of the atmosphere
    float n_distance = distance_to_surface(P + R, R + pos_y, n.y);
    // Calculate the distance from the viewpoint along the light direction to the outer edge of the atmosphere
    float s_distance = distance_to_surface(P + R, R + pos_y, lightDir.y);

    // Calculate the intersection point of the light ray with the outer edge of the atmosphere
    vec3 intersect_pos = vec3(0, R + pos_y, 0) - lightDir * s_distance;
    // Calculate the surface normal at the intersection point
    vec3 surface_normal = normalize(intersect_pos);

    vec3 c = Sun * g; // Calculate the scattered light color

    // Calculate the attenuation of light as it passes through the atmosphere
    c *= abs((exp(-t * n_distance) - exp(-t * s_distance)) / (n.y - lightDir.y)) * max(dot(lightDir, surface_normal), 0.);

    // Add a sun glare effect
    c += exp(-t * n_distance) * Sun * smoothstep(0.999, 0.9995, dot(n0, lightDir));
    return vec4(clamp(c, 0., 50.), 1);
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = vec2(2. * uv.x - 1., (2. * uv.y - 1.) / iResolution.x * iResolution.y);

    const vec3 rotation = vec3(-0.1, 0, 0);
    vec3 n = normalize((rot(vec3(Projection(uv, 0.5), 1), rotation)).xyz);
    vec2 mp = iMouse.xy / iResolution.xy;
    mp = 2. * mp - 1.;
    mp.y = mp.y / iResolution.x * iResolution.y;
    vec3 lightDir;
    if (iMouse.z != 0.) {
        lightDir = normalize((rot(vec3(Projection(mp, 0.5), 1), rotation)).xyz);
    } else {
        lightDir = normalize(vec3(0, 0.025, 1));
    }

    vec3 col = background(1500. * (1. - cos(iTime)), n, lightDir).xyz;

    col = ACESFilm(col);
    col = pow(col, vec3(1. / 2.2));
    fragColor = vec4(col, 1.0);
}
